# Français — 5e AS, séries A (lettres) et O (lettres originelles) (IPN). Contenu tiré du manuel uniquement.
# Chaque texte du manuel = une leçon : le texte (image du manuel), compréhension (questions/réponses), lexique, production.
# Les textes communs avec le manuel 5C/5D reprennent la même exploitation (questions identiques), avec les pages de ce manuel.
import importlib.util as _u, os as _os
BOOK = "FR_5AO"

def F(page, y0, y1, x0=0.07, x1=0.93, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}

def T(title, pages, figs, objectives, intro, summary, points, qa, production, extra=None, app=None):
    board = []
    for i, f in enumerate(figs):
        board.append({"h": "Le texte" + (f" ({i+1}/{len(figs)})" if len(figs) > 1 else ""), "lines": [], "fig": f})
    board.append({"h": "Compréhension", "lines": [], "table": [["Question", "Réponse"]] + [list(x) for x in qa]})
    if extra:
        board += extra
    board.append({"h": "Production", "lines": production})
    q, a = app if app else qa[0]
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": q, "a": a}, "board": board}

def S(h, lines=None, table=None):
    d = {"h": h, "lines": lines or []}
    if table: d["table"] = table
    return d

_s = _u.spec_from_file_location("_fr5cd", _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "FR_5CD.py"))
_cd = _u.module_from_spec(_s); _s.loader.exec_module(_cd)

def R(cd_title, title, pages, figs, production, keep_extra=True):
    """Reprend une leçon du manuel 5C/5D (même texte, mêmes questions) avec les pages de ce manuel."""
    src = next(l for l in _cd.LESSONS if cd_title in l["title"])
    board = []
    for i, f in enumerate(figs):
        board.append({"h": "Le texte" + (f" ({i+1}/{len(figs)})" if len(figs) > 1 else ""), "lines": [], "fig": f})
    for b in src["board"]:
        if b["h"].startswith("Le texte") or b["h"] == "Production": continue
        if b["h"] != "Compréhension" and not keep_extra: continue
        board.append(b)
    board.append({"h": "Production", "lines": production})
    return dict(src, title=title, match=[title], pages=pages, board=board)

